/**
 * Retry utilities
 */

export interface RetryOptions {
	maxAttempts: number
	baseDelayMs: number
	maxDelayMs: number
}

/**
 * Waits for the given number of milliseconds using setTimeout wrapped in a Promise.
 */
export function delay(ms: number): Promise<void> {
	return new Promise((resolve) => setTimeout(resolve, ms))
}

/**
 * Executes `fn` with retries and exponential backoff.
 *
 * - Calls `fn()` up to `options.maxAttempts` times.
 * - After a failure, waits `options.baseDelayMs * 2^attempt` ms (capped at
 *   `options.maxDelayMs`) before the next attempt.
 * - Resolves with the first successful result.
 * - Throws the last error if all attempts fail.
 */
export async function withRetry<T>(fn: () => Promise<T>, options: RetryOptions): Promise<T> {
	const { maxAttempts, baseDelayMs, maxDelayMs } = options

	let lastError: unknown

	for (let attempt = 0; attempt < maxAttempts; attempt++) {
		try {
			return await fn()
		} catch (error) {
			lastError = error
			// Only back off if there is another attempt to make
			if (attempt < maxAttempts - 1) {
				const waitMs = Math.min(baseDelayMs * 2 ** attempt, maxDelayMs)
				await delay(waitMs)
			}
		}
	}

	throw lastError
}
